import { resolveGatewayPort } from "openclaw/plugin-sdk/gateway-config-runtime";

type ViewerBaseUrlFieldName = "baseUrl" | "viewerBaseUrl";

export function buildViewerUrl(params: {
  config: OpenClawConfig;
  viewerPath: string;
  baseUrl?: string;
  viewerBaseUrl?: string;
}): string {
  const baseUrl =
    params.baseUrl?.trim() ||
    params.viewerBaseUrl?.trim() ||
    resolveGatewayPublicOrigin(params.config) ||
    resolveGatewayBaseUrl(params.config);
  const normalizedBase = normalizeViewerBaseUrl(baseUrl);
  const viewerPath = params.viewerPath.startsWith("/")
    ? params.viewerPath
    : `/${params.viewerPath}`;
  const parsedBase = new URL(normalizedBase);
  const basePath = parsedBase.pathname === "/" ? "" : parsedBase.pathname.replace(/\/+$/, "");
  parsedBase.pathname = `${basePath}${viewerPath}`;
  parsedBase.search = "";
  parsedBase.hash = "";
  return parsedBase.toString();
}

export function normalizeViewerBaseUrl(
  raw: string,
  fieldName: ViewerBaseUrlFieldName = "baseUrl",
): string {
  const parsed = URL.parse(raw);
  if (!parsed) {
    throw new Error(`Invalid ${fieldName}: ${raw}`);
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new Error(`${fieldName} must use http or https: ${raw}`);
  }
  if (parsed.search || parsed.hash) {
    throw new Error(`${fieldName} must not include query/hash: ${raw}`);
  }
  parsed.search = "";
  parsed.hash = "";
  parsed.pathname = parsed.pathname.replace(/\/+$/, "");
  return parsed.toString().replace(/\/+$/, "");
}

function resolveGatewayBaseUrl(config: OpenClawConfig): string {
  const scheme = config.gateway?.tls?.enabled ? "https" : "http";
  const port = resolveGatewayPort(config);
  const customHost = config.gateway?.customBindHost?.trim();

  if (config.gateway?.bind === "custom" && customHost) {
    return `${scheme}://${customHost}:${port}`;
  }

  // Viewer links are used by local canvas/clients; default to loopback to avoid
  // container/bridge interfaces that are often unreachable from the caller.
  return `${scheme}://127.0.0.1:${port}`;
}

/** Type guard for non-array object records at browser-safe boundaries. */
export function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

export function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((entry) => typeof entry === "string");
}

/** Coerces object-like values to records, falling back to an empty record. */
export function asRecord(value: unknown): Record<string, unknown> {
  return asOptionalObjectRecord(value) ?? {};
}

/** Reads a field only when it exists as a string. */
export function readStringField(
  record: Record<string, unknown> | null | undefined,
  key: string,
): string | undefined {
  const value = record?.[key];
  return typeof value === "string" ? value : undefined;
}

/** Returns a non-array record or undefined. */
export function asOptionalRecord(value: unknown): Record<string, unknown> | undefined {
  return isRecord(value) ? value : undefined;
}

/** Returns a non-array record or a fresh ordinary empty record. */
export function asNonArrayRecord(value: unknown): Record<string, unknown> {
  return asOptionalRecord(value) ?? {};
}

export function ensureRecord(root: Record<string, unknown>, key: string): Record<string, unknown> {
  const current = asOptionalRecord(root[key]);
  if (current) {
    return current;
  }
  const next: Record<string, unknown> = {};
  root[key] = next;
  return next;
}

/** Returns a non-array record or null. */
export function asNullableRecord(value: unknown): Record<string, unknown> | null {
  return isRecord(value) ? value : null;
}

/** Returns any object-backed record, including arrays, or undefined. */
export function asOptionalObjectRecord(value: unknown): Record<string, unknown> | undefined {
  return value && typeof value === "object" ? (value as Record<string, unknown>) : undefined;
}

/** Returns any object-backed record, including arrays, or null. */
export function asNullableObjectRecord(value: unknown): Record<string, unknown> | null {
  return asOptionalObjectRecord(value) ?? null;
}

/** Checks that every enumerable own value in a non-array record is a string. */
export function isStringRecord(value: unknown): value is Record<string, string> {
  return isRecord(value) && Object.values(value).every((entry) => typeof entry === "string");
}

/** Removes undefined fields from a fresh projection in place, retaining its identity. */
export function omitUndefinedFields<T extends object>(fields: T): T {
  for (const key in fields) {
    if (fields[key] === undefined) {
      delete fields[key];
    }
  }
  return fields;
}

/** Retains string-valued own enumerable entries from a non-array record. */
export function filterStringRecord(value: unknown): Record<string, string> | undefined {
  if (!isRecord(value)) {
    return undefined;
  }
  const entries = Object.entries(value).filter(
    (entry): entry is [string, string] => typeof entry[1] === "string",
  );
  return entries.length > 0 ? Object.fromEntries(entries) : undefined;
}

