export function asNonArrayRecord(value         )                          {
  return asOptionalRecord(value) ?? {};
}

export function ensureRecord(root                         , key        )                          {
  const current = asOptionalRecord(root[key]);
  if (current) {
    return current;
  }
  const next                          = {};
  root[key] = next;
  return next;
}

